def ids(site):return [x['id'] for x in queries if x['site']==site]
def unknown(site,detail):return dict(status='unresolved',detail=detail,search_ids=ids(site))
def meta(v,detail,sid=None,loc=None,site=None):
    a=dict(status=v,detail=detail)
    if sid:a.update(source_ids=[sid],locator=loc)
    if site:a['search_ids']=ids(site)
    return a
def count(c,n,basis,sid,loc,detail,date):return dict(object_class=c,count=n,count_basis=basis,source_id=sid,locator=loc,detail=detail,count_date=date)
def base(name,klass,cisi=False):
    return dict(canonical_name=name,status='Exploratory',revision_date=DATE,site_entity_id=name.lower().replace(' ','-'),alternative_spellings=[],country='Pakistan',province=unknown(name,'Balochistan; administrative evidence specified in publications below.'),coordinates=unknown(name,'No excavation coordinate independently verified.'),search_ids=ids(name),source_ids=[],excavation_campaigns=[],publications=[],cisi=unknown(name,'No exact site entry/page identified in consulted CISI sources.'),mahadevan_1977_count=unknown(name,'No site-specific Mahadevan1977 count/page found; no zero inferred.'),icit_count=unknown(name,'No class-based ICIT site inventory inspected; index sign occurrences are not object counts.'),reported_counts_by_class={k:unknown(name,'No class inventory or explicit zero located.') for k in ['seals','sealings','tablets','inscribed_pottery_and_graffiti','metal','other_inscribed_objects']},reported_object_counts=[],publication_metadata={},post_cisi_assessment=dict(status='no_dated_find_located',latest_cisi_coverage_year=None,find_count_basis=None,source_ids=[],search_ids=ids(name)),post_cisi_finds=[],final_report=dict(status='unresolved',title=None,source_id=None,locator=None,full_text_inspected=False,search_ids=ids(name)),present_holding=unknown(name,'Present object custody not established.'),digital_availability=[],open_problems=[],superseded_first_pass_claims=[],local_coverage_judgment='',local_corpus=dict(site=name,region='Iranian Plateau',faces=1,object_families=1,distinct_cisi_ids=int(cisi),cisi_prefixes={'Sb':1} if cisi else {},max_cisi_number_by_prefix={'Sb':4} if cisi else {},object_classes={klass:1},faces_with_period_or_time=0,faces_with_room_or_grid=int(cisi),faces_with_dimensions=int(cisi),faces_with_excavation_number=int(cisi)))

